BEGIN;
SELECT pg_advisory_xact_lock(23092026);
-- Run in a Supabase project, inside the transaction generated by npm run db:prepare.
-- Namespaced mt_* tables leave other applications' tables untouched.
CREATE TABLE IF NOT EXISTS public.mt_metadata (key text PRIMARY KEY, value text NOT NULL);
CREATE TABLE IF NOT EXISTS public.mt_profiles (
  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  role text NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin'))
);
CREATE OR REPLACE FUNCTION public.mt_create_profile() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  INSERT INTO public.mt_profiles(id) VALUES (NEW.id) ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.mt_create_profile() FROM PUBLIC;
DROP TRIGGER IF EXISTS mt_profile_created ON auth.users;
CREATE TRIGGER mt_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.mt_create_profile();
INSERT INTO public.mt_profiles(id) SELECT id FROM auth.users ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.mt_is_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (SELECT 1 FROM public.mt_profiles WHERE id = (SELECT auth.uid()) AND role = 'admin');
$$;
REVOKE ALL ON FUNCTION public.mt_is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mt_is_admin() TO anon, authenticated;
CREATE TABLE IF NOT EXISTS public.mt_places (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 160),
  type text NOT NULL CHECK (type IN ('restaurant','activity')),
  lat double precision NOT NULL CHECK (lat BETWEEN -90 AND 90),
  lng double precision NOT NULL CHECK (lng BETWEEN -180 AND 180),
  location text NOT NULL CHECK (char_length(location) BETWEEN 1 AND 160),
  description text NOT NULL CHECK (char_length(description) BETWEEN 1 AND 3000),
  description_fr text CHECK (char_length(description_fr) <= 3000),
  rating double precision CHECK (rating BETWEEN 0 AND 5),
  hours text CHECK (char_length(hours) <= 200),
  tags jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(tags) = 'array' AND jsonb_array_length(tags) <= 20),
  image text CHECK (image IS NULL OR image LIKE 'https://%' OR image LIKE '/photos/%'),
  photo_credit jsonb,
  sources jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(sources) = 'array'),
  access text NOT NULL DEFAULT 'unknown' CHECK (access IN ('unknown','open','restricted')),
  published boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.mt_saved_places (
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  place_id bigint NOT NULL REFERENCES public.mt_places(id) ON DELETE CASCADE,
  kind text NOT NULL CHECK (kind IN ('favorites','revisits')),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(user_id,place_id,kind)
);
CREATE INDEX IF NOT EXISTS mt_saved_places_place_idx ON public.mt_saved_places(place_id);
CREATE TABLE IF NOT EXISTS public.mt_rate_limits (
  key text PRIMARY KEY,
  hits integer NOT NULL,
  expires_at timestamptz NOT NULL
);
CREATE OR REPLACE FUNCTION public.mt_check_rate_limit(identifier text, ceiling integer) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE current_hits integer;
BEGIN
  IF identifier !~ '^[a-f0-9]{64}$' OR ceiling < 1 OR ceiling > 100 THEN RAISE EXCEPTION 'Invalid rate limit'; END IF;
  DELETE FROM public.mt_rate_limits WHERE expires_at < now();
  INSERT INTO public.mt_rate_limits(key,hits,expires_at) VALUES(identifier,1,now()+interval '15 minutes')
  ON CONFLICT(key) DO UPDATE SET hits = public.mt_rate_limits.hits + 1
  RETURNING hits INTO current_hits;
  RETURN current_hits <= ceiling;
END;
$$;
REVOKE ALL ON FUNCTION public.mt_check_rate_limit(text,integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.mt_check_rate_limit(text,integer) TO service_role;

ALTER TABLE public.mt_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mt_places ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mt_saved_places ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mt_metadata ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mt_rate_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.mt_profiles, public.mt_places, public.mt_saved_places, public.mt_metadata, public.mt_rate_limits FROM anon, authenticated;
GRANT SELECT ON public.mt_places, public.mt_metadata TO anon, authenticated;
GRANT SELECT ON public.mt_profiles TO authenticated;
GRANT INSERT, UPDATE, DELETE ON public.mt_places TO authenticated;
GRANT SELECT, INSERT, DELETE ON public.mt_saved_places TO authenticated;
GRANT USAGE ON SEQUENCE public.mt_places_id_seq TO authenticated;
GRANT ALL ON public.mt_profiles, public.mt_places, public.mt_saved_places, public.mt_metadata, public.mt_rate_limits TO service_role;
GRANT USAGE ON SEQUENCE public.mt_places_id_seq TO service_role;
DROP POLICY IF EXISTS mt_own_profile ON public.mt_profiles;
CREATE POLICY mt_own_profile ON public.mt_profiles FOR SELECT TO authenticated USING (id = (SELECT auth.uid()));
DROP POLICY IF EXISTS mt_read_places ON public.mt_places;
CREATE POLICY mt_read_places ON public.mt_places FOR SELECT TO anon, authenticated USING (published OR (SELECT public.mt_is_admin()));
DROP POLICY IF EXISTS mt_admin_insert ON public.mt_places;
CREATE POLICY mt_admin_insert ON public.mt_places FOR INSERT TO authenticated WITH CHECK ((SELECT public.mt_is_admin()));
DROP POLICY IF EXISTS mt_admin_update ON public.mt_places;
CREATE POLICY mt_admin_update ON public.mt_places FOR UPDATE TO authenticated USING ((SELECT public.mt_is_admin())) WITH CHECK ((SELECT public.mt_is_admin()));
DROP POLICY IF EXISTS mt_admin_delete ON public.mt_places;
CREATE POLICY mt_admin_delete ON public.mt_places FOR DELETE TO authenticated USING ((SELECT public.mt_is_admin()));
DROP POLICY IF EXISTS mt_read_saved ON public.mt_saved_places;
CREATE POLICY mt_read_saved ON public.mt_saved_places FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
DROP POLICY IF EXISTS mt_insert_saved ON public.mt_saved_places;
CREATE POLICY mt_insert_saved ON public.mt_saved_places FOR INSERT TO authenticated WITH CHECK (user_id = (SELECT auth.uid()) AND EXISTS (SELECT 1 FROM public.mt_places WHERE id = place_id AND published));
DROP POLICY IF EXISTS mt_delete_saved ON public.mt_saved_places;
CREATE POLICY mt_delete_saved ON public.mt_saved_places FOR DELETE TO authenticated USING (user_id = (SELECT auth.uid()));
DROP POLICY IF EXISTS mt_public_version ON public.mt_metadata;
CREATE POLICY mt_public_version ON public.mt_metadata FOR SELECT TO anon, authenticated USING (key = 'schema_version');
INSERT INTO public.mt_metadata(key,value) VALUES ('schema_version','1') ON CONFLICT DO NOTHING;


-- Seed once. Re-running setup preserves edits and deliberately deleted places.
DO $seed$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.mt_metadata WHERE key = 'catalogue_seeded') THEN
    INSERT INTO public.mt_places(id,name,type,lat,lng,location,description,description_fr,rating,hours,tags,image,photo_credit,sources,access)
    SELECT p.id,p.name,p.type,p.lat,p.lng,p.location,p.description,p.description_fr,p.rating,p.hours,COALESCE(p.tags,'[]'::jsonb),p.image,p.photo_credit,COALESCE(p.sources,'[]'::jsonb),COALESCE(p.access,'unknown')
    FROM jsonb_to_recordset('[{"id":1,"name":"Le Petibonum","type":"restaurant","lat":14.7111,"lng":-61.1819,"location":"Le Carbet","description":"A beachfront restaurant in Le Carbet, with Caribbean-inspired cooking and a relaxed setting by the sea.","rating":4.5,"hours":"12:00 PM - 10:00 PM","tags":["Beachfront","Creole","Seafood","Casual"],"image":"https://images.unsplash.com/photo-1544124499-58912cbddaad?auto=format&fit=crop&q=80&w=800"},{"id":2,"name":"Habitation Clément","type":"activity","lat":14.6017,"lng":-60.9083,"location":"Le François","description":"A historic estate in Le François with gardens, rum heritage, and contemporary art to explore.","rating":4.8,"hours":"9:00 AM - 6:30 PM","tags":["Culture","History","Rum Tasting","Garden"],"image":"https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&q=80&w=800"},{"id":3,"name":"Jardin de Balata","type":"activity","lat":14.6394,"lng":-61.0583,"location":"Fort-de-France","description":"A tropical botanical garden near Fort-de-France, with landscaped paths and treetop walkways.","rating":4.9,"hours":"9:00 AM - 6:00 PM","tags":["Nature","Botanical","Family Friendly","Scenic"],"image":"https://images.unsplash.com/photo-1466781783364-391814662c7e?auto=format&fit=crop&q=80&w=800"},{"id":4,"name":"Ti'' Sable","type":"restaurant","lat":14.4842,"lng":-61.0858,"location":"Les Anses-d''Arlet","description":"A restaurant by the beach in Les Anses-d’Arlet, offering a setting for lunch or dinner by the water.","rating":4.7,"hours":"11:30 AM - 11:00 PM","tags":["Romantic","Beach","Fine Dining","Sunset View"],"image":"https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&q=80&w=800"},{"id":5,"name":"Montagne Pelée Hike","type":"activity","lat":14.8111,"lng":-61.1644,"location":"Saint-Pierre","description":"A mountain hike through the landscapes of Montagne Pelée. Check access, weather, and trail conditions before setting out.","rating":4.9,"hours":"Best at sunrise","tags":["Hiking","Volcano","Challenge","Nature"],"image":"https://images.unsplash.com/photo-1551632811-561732d1e306?auto=format&fit=crop&q=80&w=800"},{"id":6,"name":"Plage des Salines","type":"activity","lat":14.4025,"lng":-60.8758,"location":"Sainte-Anne","description":"A sandy beach in Sainte-Anne, known for its coconut palms and views of the sea.","rating":4.8,"hours":"All day","tags":["Beach","Relaxation","Family","Swimming"],"image":"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&q=80&w=800"},{"id":7,"name":"Cascade Didier","type":"activity","lat":14.6533,"lng":-61.08,"location":"Fort-de-France","description":"A waterfall area in the tropical forest near Fort-de-France. Verify permitted access and current conditions before planning a visit.","rating":4.6,"hours":"9:00 AM - 4:00 PM","tags":["Hiking","Waterfall","Adventure","Hidden Gem"],"image":"https://images.unsplash.com/photo-1433086966358-54859d0ed716?auto=format&fit=crop&q=80&w=800"},{"id":8,"name":"Le Zandoli","type":"restaurant","lat":14.555,"lng":-61.052,"location":"Les Trois-Îlets","description":"A restaurant at La Suite Villa in Les Trois-Îlets, with views towards the Bay of Fort-de-France.","rating":4.8,"hours":"7:00 PM - 10:30 PM","tags":["Fine Dining","Panoramic View","Modern Creole"],"image":"https://images.unsplash.com/photo-1550966842-2849a2244845?auto=format&fit=crop&q=80&w=800"},{"id":9,"name":"Presqu''île de la Caravelle","type":"activity","lat":14.77,"lng":-60.91,"location":"Tartane","description":"A nature reserve on the Caravelle peninsula, with coastal trails, dry forest, and mangrove landscapes.","rating":4.7,"hours":"Sunrise to Sunset","tags":["Nature Reserve","Hiking","Coastal","Views"],"image":"https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&q=80&w=800"},{"id":10,"name":"Chez Carole","type":"restaurant","lat":14.6067,"lng":-61.0667,"location":"Fort-de-France","description":"A place to discover Creole cooking in the central market area of Fort-de-France.","rating":4.4,"hours":"11:00 AM - 3:00 PM","tags":["Market Food","Traditional","Local","Bustling"],"image":"https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&q=80&w=800"},{"id":11,"name":"La Savane des Esclaves","type":"activity","lat":14.5383,"lng":-61.0267,"location":"Les Trois-Îlets","description":"An open-air museum exploring Martinique’s history, the legacy of slavery, and traditional ways of life.","rating":4.9,"hours":"9:00 AM - 5:30 PM","tags":["History","Museum","Education","Village"],"image":"https://images.unsplash.com/photo-1541963463532-d68292c34b19?auto=format&fit=crop&q=80&w=800"},{"id":12,"name":"Piliers du Sud","type":"restaurant","lat":14.475,"lng":-60.871,"location":"Le Marin","description":"A seafood restaurant overlooking the marina in Le Marin.","rating":4.5,"hours":"12:00 PM - 11:00 PM","tags":["Seafood","Marina View","Cocktails"],"image":"https://images.unsplash.com/photo-1467003909585-2f8a72700288?auto=format&fit=crop&q=80&w=800"},{"id":13,"name":"Madiana Cinéma Multiplex","type":"activity","lat":14.6148,"lng":-61.0963,"location":"Schœlcher","description":"A cinema complex in Schœlcher. Check the current programme, language, and screening times before visiting.","rating":4.6,"hours":"1:30 PM - 11:30 PM","tags":["Cinema","Entertainment","Extracurricular","Indoor","Popcorn"],"image":"https://images.unsplash.com/photo-1517604931442-7e0c8ed2963c?auto=format&fit=crop&q=80&w=800"},{"id":14,"name":"Cinéma Le Rex","type":"activity","lat":14.6038,"lng":-61.0694,"location":"Fort-de-France","description":"A cinema listing in Fort-de-France. Confirm the venue’s current programme and opening status before visiting.","rating":4.3,"hours":"4:00 PM - 10:00 PM","tags":["Cinema","Entertainment","Extracurricular","Downtown"],"image":"https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?auto=format&fit=crop&q=80&w=800"},{"id":15,"name":"Plaza Bowling d''Acajou","type":"activity","lat":14.6111,"lng":-61.018,"location":"Le Lamentin","description":"A bowling and leisure venue in Le Lamentin. Contact the venue for current activities, prices, and availability.","rating":4.7,"hours":"2:00 PM - 12:00 AM","tags":["Bowling","Arcade","Extracurricular","Family Friendly","Nightlife"],"image":"https://images.unsplash.com/photo-1538388149343-8d9df58d5f70?auto=format&fit=crop&q=80&w=800"},{"id":16,"name":"Acro''Kart","type":"activity","lat":14.5366,"lng":-61.0112,"location":"Les Trois-Îlets","description":"An outdoor go-karting venue at the Village de la Poterie in Les Trois-Îlets. Check session times and participation requirements.","rating":4.8,"hours":"2:00 PM - 10:00 PM","tags":["Karting","Racing Carts","Extracurricular","Adrenaline","Speed"],"image":"https://images.unsplash.com/photo-1568605117036-5fe5e7bab0b7?auto=format&fit=crop&q=80&w=800"},{"id":17,"name":"Laser West Laser Tag","type":"activity","lat":14.6133,"lng":-61.021,"location":"Le Lamentin","description":"A laser tag activity in Le Lamentin. Check current opening hours and booking requirements with the venue.","rating":4.6,"hours":"1:00 PM - 10:00 PM","tags":["Laser Tag","Games","Extracurricular","Family Friendly","Indoor"],"image":"https://images.unsplash.com/photo-1511512578047-dfb367046420?auto=format&fit=crop&q=80&w=800"},{"id":18,"name":"Hippopotamus Steakhouse","type":"restaurant","lat":14.6062,"lng":-61.021,"location":"Le Lamentin","description":"A steakhouse in Le Lamentin, with grilled dishes and options for a meal with family or friends.","rating":4.3,"hours":"11:30 AM - 11:00 PM","tags":["Steakhouse","French","Classy","Burgers","Le Lamentin"],"image":"https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&q=80&w=800"},{"id":19,"name":"Tori Sushi","type":"restaurant","lat":14.6115,"lng":-61.0255,"location":"Le Lamentin","description":"A Japanese restaurant in Le Lamentin, with sushi and other Japanese-inspired dishes.","rating":4.5,"hours":"12:00 PM - 2:30 PM, 6:30 PM - 10:30 PM","tags":["Sushi","Japanese","Classy","Asian Fusion"],"image":"https://images.unsplash.com/photo-1579871494447-9811cf80d66c?auto=format&fit=crop&q=80&w=800"},{"id":20,"name":"McDonald''s","type":"restaurant","lat":14.6111,"lng":-61.024,"location":"Le Lamentin","description":"A fast-food restaurant in Le Lamentin. Check the local menu and opening hours before visiting.","rating":4.1,"hours":"7:00 AM - 12:00 AM","tags":["Fast Food","Burgers","Quick Bite","Family Friendly"],"image":"https://images.unsplash.com/photo-1606755962773-d324e0a13086?auto=format&fit=crop&q=80&w=800"},{"id":21,"name":"Bokay Burger (BKB)","type":"restaurant","lat":14.5684,"lng":-60.985,"location":"Ducos","description":"A local burger restaurant in Ducos. Check the current menu and opening hours with the venue.","rating":4.7,"hours":"11:30 AM - 10:30 PM","tags":["BKB","Local Burgers","Fried Chicken","Quick Bite","Local Favorite"],"image":"https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&q=80&w=800"},{"id":22,"name":"Chez Fredo","type":"restaurant","lat":14.4682,"lng":-60.9295,"location":"Sainte-Luce","description":"A place for Creole food in Sainte-Luce. Check with the venue for current service times and events.","rating":4.8,"hours":"12:00 PM - 11:30 PM","tags":["Creole","Live Music","Beachside","Traditional","Local Favorite","South of Island"],"image":"https://images.unsplash.com/photo-1578474846511-04ba529f0b88?auto=format&fit=crop&q=80&w=800"},{"id":23,"name":"Le Balaou","type":"restaurant","lat":14.4681,"lng":-60.9248,"location":"Sainte-Luce","description":"A seaside restaurant in Sainte-Luce, with seafood and local dishes.","rating":4.6,"hours":"12:00 PM - 10:30 PM","tags":["Seafood","Beachside","Local","Cocktails","South of Island"],"image":"https://images.unsplash.com/photo-1467003909585-2f8a72700288?auto=format&fit=crop&q=80&w=800"},{"id":24,"name":"La Dunette","type":"restaurant","lat":14.435,"lng":-60.8814,"location":"Sainte-Anne","description":"A waterfront hotel and restaurant in Sainte-Anne, with a terrace overlooking the sea.","rating":4.5,"hours":"11:00 AM - 11:00 PM","tags":["Waterfront","Cocktails","South of Island","Creole","Sunset Views"],"image":"https://images.unsplash.com/photo-1540189549336-e6e99c3679fe?auto=format&fit=crop&q=80&w=800"}]'::jsonb) AS p(id bigint,name text,type text,lat double precision,lng double precision,location text,description text,description_fr text,rating double precision,hours text,tags jsonb,image text,photo_credit jsonb,sources jsonb,access text)
    ON CONFLICT(id) DO NOTHING;
    PERFORM setval(pg_get_serial_sequence('public.mt_places','id'),GREATEST(COALESCE((SELECT max(id) FROM public.mt_places),1),(SELECT last_value FROM public.mt_places_id_seq)),true);
    INSERT INTO public.mt_metadata(key,value) VALUES('catalogue_seeded','1');
  END IF;
END;
$seed$;
COMMIT;
